import sys; sys.path.insert(0,'gen')
from piezas2 import *
W,H=1387,813
def kpi(v,t,f=AZUL,c='#FFFFFF'):
    return f'<div style="padding: 18px; border-radius: 22px; background: {f}; color: {c}; {"box-shadow: 0 4px 0 "+HONDO if f==AZUL else "border: 1px solid "+BORDE}; display: flex; flex-direction: column; gap: 4px"><strong style="{TIT}; font-size: 40px; line-height: 1">{v}</strong><span style="font-size: 14px; font-weight: 700">{t}</span></div>'
def lista(titulo, items, ic='check', color='#137140'):
    li=''.join(f'<li style="display: flex; gap: 10px; align-items: flex-start; padding: 8px 0; border-top: 1px solid {BORDE}; font-size: 14px">{svg(IC[ic],color,18)}<span>{t}</span></li>' for t in items)
    return f'<section style="padding: 18px; border-radius: 24px; background: #FFFFFF; border: 1px solid {BORDE}; box-shadow: {ELEV1}">{etiqueta(titulo)}<ul style="list-style: none; margin: 8px 0 0; padding: 0">{li}</ul></section>'
html=f'''<div style="width: {W}px; height: {H}px; box-sizing: border-box; padding: 34px 40px; background: #F6F7F9; font-family: 'DM Sans', system-ui, sans-serif; color: {TINTA}; display: flex; flex-direction: column; gap: 18px">
  <div style="display: flex; justify-content: space-between; align-items: flex-end"><div style="display: flex; flex-direction: column; gap: 6px">{etiqueta("REVISIÓN · 08/11/2026", AZUL)}<h1 style="margin: 0; {TIT}; font-size: 40px; line-height: 1">Revisión UX/UI de todo el diseño</h1><span style="font-size: 15px; color: {SUAVE}">161 pantallas (una de escritorio), 16 recorridos con pantallas y 17 flujos revisados en el navegador, con chequeos automáticos y a ojo.</span></div>{chip("Datos de prueba en todas las pantallas","check","exito")}</div>
  <div style="display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px">{kpi('0','errores de accesibilidad (axe, WCAG 2 A y AA)')}{kpi('0','botones o enlaces de menos de 44 px','#FFFFFF',TINTA)}{kpi('0','textos de menos de 11 px','#FFFFFF',TINTA)}{kpi('0','pantallas con contenido tapado por los botones fijos','#FFFFFF',TINTA)}</div>
  <div style="display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px">
    {lista("LO QUE SE CORRIGIÓ EN ESTA REVISIÓN",["Contraste: días pasados, franjas ocupadas y textos celestes sobre azul ahora cumplen 4,5 : 1.","Interruptores: toda la fila es el control y tiene nombre para el lector de pantalla.","Pestañas, avisos y enlaces de texto con área táctil de 44 px.","Etiquetas de 9 y 10 px subidas a 11 px.","Roles ARIA: chips sin «tablist», botones con rol, colores de la remera con nombre.","Montos y unidades que ya no se parten en dos líneas; palabras largas que se cortan con guion."])}
    {lista("REGLAS DEL SISTEMA QUE SE RESPETAN",["Cabecera azul en Inicio, Cuenta, Ayuda y Camino; barra compacta con volver en el resto.","Pestañas flotantes de vidrio solo en las cinco pantallas raíz.","Una acción principal por pantalla, fija abajo, con base que se hunde.","Estados con ícono y texto; montos en Archivo ensanchado y cifras tabulares.","Una palabra con marcador amarillo por título; Handys en vacíos, éxitos y errores.","Oscuro solo donde ayuda: Modo trabajo no, nivel, cámara, QR y escaneo sí."],'check',AZUL)}
    {lista("PARA EL DESARROLLO",["Movimiento con View Transitions y celebraciones; todo se apaga con «reducir movimiento».","Esqueletos de carga, vacíos y errores para cada pantalla que trae datos.","Texto al 200 % y ancho de 320 px en el código real (acá se diseñó a 390 × 844).","Probar a mano con VoiceOver y TalkBack, y la AR en un Android y un iPhone.","Pasar a Figma primero las piezas comunes como componentes (design/deluxe)."],'flecha' if 'flecha' in IC else 'check',HONDO)}
  </div>
  <section style="padding: 18px; border-radius: 24px; background: {NOCHE}; color: #FFFFFF; display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px">
    {''.join(f'<div style="display: flex; flex-direction: column; gap: 4px"><span style="font-size: 11px; font-weight: 800; letter-spacing: 1.5px; color: {AMARILLO}">{a}</span><span style="font-size: 14px">{b}</span></div>' for a,b in [('DECISIONES ABIERTAS','Tokens propios de la app o tocar la landing; plan de Meshy.'),('LEGAL','Antecedentes por archivo, montos y premios del camino, avisos de privacidad.'),('PROVEEDORES','SMS para acceso y MFA; catálogo real de ferreterías aliadas.'),('COMERCIAL','Condiciones con las ferreterías; kit de bienvenida (remera y manual).')])}
  </section>
</div>'''
doc=documento('Revisión UX/UI','').replace(f'<div style="width: 390px; height: 844px; box-sizing: border-box; background: #FFFFFF; font-family: \'DM Sans\', system-ui, sans-serif; color: {TINTA}; overflow: hidden; position: relative">\n\n</div>', html).replace('{"width":390,"height":844}',f'{{"width":{W},"height":{H}}}')
open('deluxe/project/UX-Revision.dc.html','w').write(doc)
print('ok')
